import pytest
from candidate import strlen

class TestStrlen:
    def test_strlen_empty_string(self):
        assert strlen('') == 0

    def test_strlen_single_character(self):
        assert strlen('a') == 1

    def test_strlen_multiple_characters(self):
        assert strlen('abc') == 3

    def test_strlen_long_string(self):
        assert strlen('abcdefghijklmnopqrstuvwxyz') == 26

    def test_strlen_with_spaces(self):
        assert strlen('a b c') == 3

    def test_strlen_with_numbers(self):
        assert strlen('a1b2c3') == 3

    def test_strlen_with_special_characters(self):
        assert strlen('a!b@c#') == 3

    def test_strlen_with_mixed_case(self):
        assert strlen('Abc123') == 6

    def test_strlen_with_unicode(self):
        assert strlen('a\u00b2b\u03b1c') == 3

if __name__ == '__main__':
    pytest.main([__file__])
